# source clientShortcuts.sh <owner client process id> <visitor client process id>
# The stage 5 and 6 shakeout's shortcuts on peridothousing: e and c evaluate and command on the owner's client,
# ev and cv on the visitor's; the rest read or drive the test plot (Claudehousing's, access list 100077).
L=/c/Onyx/tools/gameTest/lcEmu.sh; P=${1:?owner client process id}; V=${2:?visitor client process id}
e(){ bash $L command $P evaluate "$1" | grep '"value"' | cut -c1-1200; }
c(){ bash $L command $P command "$1" | tr -d '\n' | cut -c1-900; echo; }
ev(){ bash $L command $V evaluate "$1" | grep '"value"' | cut -c1-1200; }
cv(){ bash $L command $V command "$1" | tr -d '\n' | cut -c1-900; echo; }
w(){ powershell -NoProfile -Command "Start-Sleep -Milliseconds $1"; }
lists(){ e 'A=${PeridotEmu.Value[character.ownedRealEstates]} ${PeridotEmu.Value[character.ownedRealEstates.0]} ${PeridotEmu.Value[character.ownedRealEstates.1]} B=${PeridotEmu.Value[character.ownedItemRealEstates]} ${PeridotEmu.Value[character.ownedItemRealEstates.0]} C=${PeridotEmu.Value[character.archivedRealEstates]} ${PeridotEmu.Value[character.archivedRealEstates.0]} ${PeridotEmu.Value[character.archivedRealEstates.1]}'; }
inv(){ e '23=${InvSlot[23].Item.Name}|24=${InvSlot[24].Item.Name}|25=${InvSlot[25].Item.Name}|26=${InvSlot[26].Item.Name}|27=${InvSlot[27].Item.Name}|28=${InvSlot[28].Item.Name}|29=${InvSlot[29].Item.Name}|30=${InvSlot[30].Item.Name}|31=${InvSlot[31].Item.Name}|32=${InvSlot[32].Item.Name}|cursor=${Cursor.Name}|free=${Me.FreeInventory}'; }
