VLOG="/c/Games/EverQuest - peridothousing/Logs/eqlog_Claudevisitor_Peridot.txt"
OLOG="/c/Games/EverQuest - peridothousing/Logs/eqlog_Claudehousing_Peridot.txt"
vmenuAt(){ cv "/face fast loc $1"; w 700; bash $L command $V click ${2:-960} ${3:-250} right >/dev/null; w 700; bash $L command $V menu | tr -d '\n'; echo; }
menuAt(){ c "/face fast loc $1"; w 700; bash $L command $P click ${2:-960} ${3:-250} right >/dev/null; w 700; bash $L command $P menu | tr -d '\n'; echo; }
cell(){ local n=$(( ($1) * 7 + ($2) )); local chain='Window[RealEstateManageWnd].Child[REMW_Permissions_List].FirstChild'; local i; for ((i=0;i<n;i++)); do chain="$chain.Next"; done; echo "$chain"; }
cellState(){ local k="$(cell $1 $2).FirstChild"; bash $L command ${3:-$P} evaluate "checked=\${$k.Checked} enabled=\${$k.Enabled}" | grep '"value"'; }
cellClick(){ local k="$(cell $1 $2).FirstChild"; bash $L command ${3:-$P} evaluate "\${$k.LeftMouseUp}" >/dev/null; }
bringVisitor(){ c "#goto ${1:-310} ${2:--240} 3.75" >/dev/null; w 600; c "#summon Claudevisitor" >/dev/null; w 1500; c "#goto 322 -229 3.75" >/dev/null; w 500; ev 'visitor at ${Me.Y} ${Me.X} ${Me.Z} in ${Zone.ShortName}'; }
nameInto(){ e "\${Window[RealEstateManageWnd].Child[REMW_Name_EditBox].SetText[$1]}" >/dev/null; w 300; c "/notify RealEstateManageWnd REMW_Access_Combobox listselect $2" >/dev/null; w 300; c "/notify RealEstateManageWnd REMW_Add_Btn leftmouseup"; w 1800; e 'list=${Window[RealEstateManageWnd].Child[REMW_Name_List].Items} 1=${Window[RealEstateManageWnd].Child[REMW_Name_List].List[1,1]}/${Window[RealEstateManageWnd].Child[REMW_Name_List].List[1,2]} 2=${Window[RealEstateManageWnd].Child[REMW_Name_List].List[2,1]}/${Window[RealEstateManageWnd].Child[REMW_Name_List].List[2,2]}'; masks; vmasks; }
vmenus(){ echo -n "hut: "; vmenuAt -264,350 960 300 | tail -1; cv "/keypress esc" >/dev/null; echo -n "chair: "; vmenuAt -250,300 960 200 | tail -1; cv "/keypress esc" >/dev/null; echo -n "forge: "; vmenuAt -252,320 960 300 | tail -1; cv "/keypress esc" >/dev/null; }
unname(){ c "/notify RealEstateManageWnd REMW_Name_List listselect ${1:-1}" >/dev/null; w 400; c "/notify RealEstateManageWnd REMW_Remove_Btn leftmouseup"; w 1500; masks; }
regroup(){ unname 1 >/dev/null; nameInto Claudevisitor $1; }
